// ---------- Números por extenso (pt-BR) ----------
const UN = ['zero', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove', 'dez', 'onze', 'doze', 'treze', 'quatorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
const DZ = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
const CT = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];
function ate999(n, fem) {
  if (n === 100) return 'cem';
  const c = Math.floor(n / 100), r = n % 100, p = [];
  if (c) p.push(fem && c > 1 ? CT[c].replace(/os$/, 'as') : CT[c]);
  if (r) {
    let s = r < 20 ? UN[r] : DZ[Math.floor(r / 10)] + (r % 10 ? ' e ' + UN[r % 10] : '');
    if (fem) s = s.replace(/\bum$/, 'uma').replace(/\bdois$/, 'duas');
    p.push(s);
  }
  return p.join(' e ');
}
function extenso(n, fem) {
  if (!Number.isInteger(n) || n < 0 || n > 999999999) throw new Error('Número fora do limite: ' + n);
  if (n === 0) return 'zero';
  const mi = Math.floor(n / 1e6), mil = Math.floor((n % 1e6) / 1000), resto = n % 1000, g = [];
  if (mi) g.push(mi === 1 ? 'um milhão' : ate999(mi, false) + ' milhões');
  if (mil) g.push(mil === 1 ? 'mil' : ate999(mil, fem) + ' mil');
  if (resto) g.push(ate999(resto, fem));
  if (g.length === 1) return g[0];
  const ult = g.pop();
  const comE = resto ? (resto < 100 || resto % 100 === 0) : (mil < 100 || mil % 100 === 0);
  return g.join(' ') + (comE ? ' e ' : ' ') + ult;
}
function reaisExtenso(n) { const s = extenso(n, false); return s + (n === 1 ? ' real' : (n % 1e6 === 0 ? ' de reais' : ' reais')); }

// ---------- Formatação ----------
const UF_NOME = { AC: 'Acre', AL: 'Alagoas', AP: 'Amapá', AM: 'Amazonas', BA: 'Bahia', CE: 'Ceará', DF: 'Distrito Federal', ES: 'Espírito Santo', GO: 'Goiás', MA: 'Maranhão', MT: 'Mato Grosso', MS: 'Mato Grosso do Sul', MG: 'Minas Gerais', PA: 'Pará', PB: 'Paraíba', PR: 'Paraná', PE: 'Pernambuco', PI: 'Piauí', RJ: 'Rio de Janeiro', RN: 'Rio Grande do Norte', RS: 'Rio Grande do Sul', RO: 'Rondônia', RR: 'Roraima', SC: 'Santa Catarina', SP: 'São Paulo', SE: 'Sergipe', TO: 'Tocantins' };
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const so = (s) => String(s == null ? '' : s).replace(/\D/g, '');
const milhar = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const dinheiro = (n) => milhar(n) + ',00';
const fmtCPF = (c) => c.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
const fmtCEP = (c) => c.replace(/(\d{5})(\d{3})/, '$1-$2');
const txt = (s) => String(s == null ? '' : s).trim().replace(/\s+/g, ' ');
const vazio = (s) => !txt(s);
function tituloNome(nome) { return txt(nome).toLowerCase().split(' ').map((w, i) => (i > 0 && /^(da|de|do|das|dos|e)$/.test(w)) ? w : w.charAt(0).toUpperCase() + w.slice(1)).join(' '); }
function cpfValido(c) {
  if (!/^\d{11}$/.test(c) || /^(\d)\1{10}$/.test(c)) return false;
  for (const t of [9, 10]) { let s = 0; for (let i = 0; i < t; i++) s += +c[i] * (t + 1 - i); if (((s * 10) % 11) % 10 !== +c[t]) return false; }
  return true;
}
// Capital: aceita 21000 | 21.000 | 21.000,00 | 21000,00 | R$ 21.000,00. Qualquer outra forma (10.0000, 1,5, -) = inválido.
function lerCapital(v) {
  let s = txt(v).replace(/^R\$\s*/i, '').replace(/\s/g, '').replace(/,00$/, '');
  if (/^\d+$/.test(s)) return Number(s);
  if (/^\d{1,3}(\.\d{3})+$/.test(s)) return Number(s.replace(/\./g, ''));
  return NaN;
}
// RG: precisa ter pelo menos 5 dígitos e não pode ser frase (ex.: 'Mandar pelo whats')
function rgValido(rg) { const r = txt(rg); return so(r).length >= 5 && !/[a-wyz]{2,}/i.test(r); }
function dataBR(d) { // aceita AAAA-MM-DD ou DD/MM/AAAA
  const s = txt(d); let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return { d: +m[3], m: +m[2], a: +m[1] };
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); if (m) return { d: +m[1], m: +m[2], a: +m[3] };
  return null;
}
const dd = (n) => String(n).padStart(2, '0');
function idade(nasc, hoje) { let i = hoje.a - nasc.a; if (hoje.m < nasc.m || (hoje.m === nasc.m && hoje.d < nasc.d)) i--; return i; }

// ---------- Palavras por gênero ----------
function g(fem, f, m) { return fem ? f : m; }
function estadoCivil(s, fem) {
  const e = txt(s.estado_civil).toLowerCase(), rb = txt(s.regime_bens).toLowerCase();
  const regime = rb ? ' sob o regime de ' + rb : '';
  if (e.startsWith('solteir')) return g(fem, 'solteira', 'solteiro');
  if (e.startsWith('casad')) return g(fem, 'casada', 'casado') + regime;
  if (e.startsWith('divorciad')) return g(fem, 'divorciada', 'divorciado');
  if (e.startsWith('viúv') || e.startsWith('viuv')) return g(fem, 'viúva', 'viúvo');
  if (e.startsWith('união') || e.startsWith('uniao')) return 'convivente em união estável' + regime;
  if (e.startsWith('separad')) return g(fem, 'separada judicialmente', 'separado judicialmente');
  return null;
}
function endereco(e) {
  const comp = txt(e.complemento) ? ' – ' + txt(e.complemento) : '';
  return `${txt(e.logradouro)}, nº ${txt(e.numero)}${comp} – Bairro ${txt(e.bairro)}`;
}

// ---------- Conferência + montagem ----------
function montar(d, hoje) {
  const erros = [], avisos = [];
  const tipo = d.tipo; // 'SLU' | 'LTDA' | 'EI'
  const socios = d.socios || [];
  if (tipo === 'EI') return { erros: ['Empresário Individual: não tem contrato (o VRE gera o documento).'], avisos, tipo };
  if (!['SLU', 'LTDA'].includes(tipo)) erros.push('Natureza jurídica não definida — Redacted precisa escolher (Unipessoal ou Limitada).');
  if (tipo === 'SLU' && socios.length !== 1) erros.push(`Unipessoal precisa de exatamente 1 sócio (vieram ${socios.length}).`);
  if (tipo === 'LTDA' && socios.length < 2) erros.push(`Limitada precisa de 2 ou mais sócios (vieram ${socios.length}).`);
  if (vazio(d.razao_social)) erros.push('Nome da empresa (razão social) em branco.');
  if (d.integralizacao && /bens/i.test(d.integralizacao)) erros.push('Integralização em bens: contrato deve ser feito manualmente (modelo prevê só dinheiro).');
  let capital = lerCapital(d.capital);
  if (!(capital > 0)) { erros.push(`Capital social inválido ("${txt(d.capital)}") — escrever só o valor em reais, ex.: 10000 ou 10.000,00.`); capital = 0; }
  else if (capital < 100) { erros.push(`Capital social muito baixo (R$ ${dinheiro(capital)}) — confirmar com o cliente.`); }
  if (vazio(d.objeto_social)) erros.push('Objeto social em branco (Redacted define a partir das atividades).');
  const sede = d.sede || {};
  for (const k of ['logradouro', 'numero', 'bairro', 'cidade']) if (vazio(sede[k])) erros.push(`Endereço da empresa: falta ${k}.`);
  const cepSede = so(sede.cep); if (cepSede.length !== 8) erros.push(`CEP da empresa inválido ("${txt(sede.cep)}").`);
  const ufSede = txt(sede.uf).toUpperCase(); if (!UF_NOME[ufSede]) erros.push(`Estado (UF) da empresa inválido ("${txt(sede.uf)}").`);

  // sócios
  const cpfs = new Set(); let somaPct = 0;
  const S = socios.map((s, i) => {
    const rot = `Sócio ${i + 1} (${txt(s.nome) || 'sem nome'})`;
    const fem = /^f/i.test(txt(s.genero)); if (!/^(f|m)/i.test(txt(s.genero))) erros.push(`${rot}: gênero não informado.`);
    for (const [k, nome] of [['nome', 'nome'], ['nacionalidade', 'nacionalidade'], ['profissao', 'profissão'], ['rg', 'RG'], ['rg_orgao', 'órgão emissor do RG'], ['rg_uf', 'UF do RG']]) if (vazio(s[k])) erros.push(`${rot}: falta ${nome}.`);
    if (!vazio(s.rg) && !rgValido(s.rg)) erros.push(`${rot}: RG inválido ("${txt(s.rg)}") — precisa do número completo.`);
    const cpf = so(s.cpf); if (!cpfValido(cpf)) erros.push(`${rot}: CPF inválido ("${txt(s.cpf)}").`); else if (cpfs.has(cpf)) erros.push(`${rot}: CPF repetido em outro sócio.`); cpfs.add(cpf);
    const nasc = dataBR(s.nascimento); if (!nasc) erros.push(`${rot}: data de nascimento inválida ("${txt(s.nascimento)}").`);
    else if (idade(nasc, hoje) < 18) erros.push(`${rot}: menor de 18 anos — exige tratamento especial (emancipação/assistência).`);
    const ec = estadoCivil(s, fem); if (!ec) erros.push(`${rot}: estado civil não reconhecido ("${txt(s.estado_civil)}").`);
    if (/^(casad|uni)/i.test(txt(s.estado_civil)) && vazio(s.regime_bens)) erros.push(`${rot}: casado(a)/união estável sem regime de bens.`);
    const e = s.endereco || {}; for (const k of ['logradouro', 'numero', 'bairro', 'cidade']) if (vazio(e[k])) erros.push(`${rot}: endereço residencial sem ${k}.`);
    const cep = so(e.cep); if (cep.length !== 8) erros.push(`${rot}: CEP residencial inválido ("${txt(e.cep)}").`);
    const uf = txt(e.uf).toUpperCase(); if (!UF_NOME[uf]) erros.push(`${rot}: UF residencial inválida ("${txt(e.uf)}").`);
    const pct = tipo === 'SLU' ? 100 : Number(String(s.percentual).replace(',', '.'));
    if (!(pct > 0 && pct <= 100)) erros.push(`${rot}: % de participação inválido ("${txt(s.percentual)}").`); else somaPct += pct;
    let conselho = '';
    if (!vazio(s.conselho)) { const m = txt(s.conselho).match(/^(.*?)[\s:nº°-]*(\d[\d./-]*)$/i); conselho = m ? `, ${g(fem, 'inscrita', 'inscrito')} no ${m[1].trim()} sob o nº ${m[2]}` : `, ${g(fem, 'inscrita', 'inscrito')} no ${txt(s.conselho)}`; }
    const rgTxt = `${txt(s.rg)} ${txt(s.rg_orgao).toUpperCase()}/${txt(s.rg_uf).toUpperCase()}`;
    const qualif = [txt(s.nacionalidade).toLowerCase(), ec, 'maior', nasc ? `${g(fem, 'nascida', 'nascido')} em ${dd(nasc.d)}/${dd(nasc.m)}/${nasc.a}` : '', txt(s.profissao).toLowerCase()].join(', ')
      + `, ${g(fem, 'portadora', 'portador')} da cédula de identidade RG nº ${rgTxt}, CPF nº ${fmtCPF(cpf)}${conselho}, ${g(fem, 'residente e domiciliada', 'residente e domiciliado')} na ${endereco(e)}, na Cidade de ${txt(e.cidade)}, Estado de ${UF_NOME[uf] || uf}, CEP ${fmtCEP(cep)}`;
    return { fem, pct, rot, nome: txt(s.nome).toUpperCase(), titulo: tituloNome(s.nome), qualif, rg: rgTxt, adm: /^s/i.test(txt(s.administrador)) || tipo === 'SLU', pro: /^s/i.test(txt(s.pro_labore)) };
  });
  if (tipo === 'LTDA' && Math.abs(somaPct - 100) > 0.001) erros.push(`Soma das participações = ${somaPct}% (precisa dar 100%).`);
  S.forEach((s) => { s.quotas = Math.round(capital * s.pct / 100); });
  if (capital && S.length && S.reduce((a, s) => a + s.quotas, 0) !== capital) erros.push('Percentuais não dividem o capital em quotas inteiras de R$ 1,00 — conferir.');
  if (S.length && !S.some((s) => s.adm)) erros.push('Nenhum sócio marcado como administrador.');
  // Regra da Legalização (Redacted, 16/10/2026): em sociedade (2+ sócios), o sócio administrador é obrigado a retirar pró-labore
  if (tipo === 'LTDA') S.filter((s) => s.adm && !s.pro).forEach((s) => erros.push(`${s.rot}: é administrador(a) e não marcou pró-labore — em sociedade, o administrador é obrigado a retirar pró-labore. Confirmar com o cliente.`));
  if (S.some((s) => s.pro && !s.adm)) avisos.push('Sócio não administrador marcado com pró-labore — conferir.');
  if (erros.length) return { erros, avisos, tipo };

  const cidade = txt(sede.cidade), uf = UF_NOME[ufSede];
  const comum = {
    RAZAO_SOCIAL: txt(d.razao_social).toUpperCase(), SEDE_LOGRADOURO: `${txt(sede.logradouro)}, nº ${txt(sede.numero)}${txt(sede.complemento) ? ' – ' + txt(sede.complemento) : ''}`,
    SEDE_BAIRRO: txt(sede.bairro), SEDE_CIDADE: cidade, SEDE_ESTADO: uf, SEDE_CEP: fmtCEP(cepSede),
    CAPITAL: dinheiro(capital), CAPITAL_EXTENSO: reaisExtenso(capital), QUOTAS: milhar(capital), QUOTAS_EXTENSO: extenso(capital, true),
    OBJETO_SOCIAL: txt(d.objeto_social), FORO_CIDADE: txt(d.foro_cidade) || cidade, FORO_ESTADO: txt(d.foro_estado) || uf,
    LOCAL_DATA: `${cidade}, ${hoje.d} de ${MESES[hoje.m - 1]} de ${hoje.a}`,
  };
  const temPro = S.some((s) => s.adm && s.pro);
  if (tipo === 'SLU') {
    const s = S[0], f = s.fem;
    Object.assign(comum, {
      NOME: s.nome, NOME_TITULO: s.titulo, QUALIFICACAO: s.qualif, RG: s.rg,
      PRO_LABORE_OPCAO: s.pro ? 'optou em fazer' : 'optou em não fazer',
      T_DA_SOCIA: g(f, 'da sócia', 'do sócio'), T_A_SOCIA: g(f, 'a sócia', 'o sócio'), T_A_SOCIA_M: g(f, 'A sócia', 'O sócio'), T_PELA_SRA: g(f, 'pela Sra.', 'pelo Sr.'),
      T_ADMINISTRADORA: g(f, 'administradora', 'administrador'), T_INTERDITADA: g(f, 'interditada', 'interditado'), T_IMPEDIDA: g(f, 'impedida', 'impedido'),
    });
    return { erros, avisos, tipo, campos: comum, socios: [] };
  }
  const adms = S.filter((s) => s.adm);
  let administracao;
  if (adms.length === S.length) administracao = S.length === 2 ? 'ambos os sócios, em conjunto ou isoladamente' : 'todos os sócios, em conjunto ou isoladamente';
  else if (adms.length === 1) { administracao = `${adms[0].nome}, ${g(adms[0].fem, 'sócia administradora', 'sócio administrador')}`; avisos.push('Só 1 sócio administra: a cláusula de administração diz "cabendo-lhes" — Redacted conferir a concordância.'); }
  else administracao = `os sócios ${adms.map((s) => s.nome).join(' e ')}, em conjunto ou isoladamente`;
  Object.assign(comum, { ADMINISTRACAO: d.administracao_texto ? txt(d.administracao_texto) : administracao, PRO_LABORE_OPCAO: temPro ? 'fazer' : 'não fazer' });
  const socLoop = S.map((s, i) => ({ N: String(i + 1), NOME: s.nome, QUALIFICACAO: s.qualif, QUOTAS_SOCIO: milhar(s.quotas), VALOR_SOCIO: dinheiro(s.quotas), RG: s.rg }));
  return { erros, avisos, tipo, campos: comum, socios: socLoop };
}


