const r = $('Preparar registro').first().json;
const conv = $('Converter resposta do formulario').first().json;
const nomes = { SLU: 'Sociedade Limitada Unipessoal', LTDA: 'Sociedade Limitada', EI: 'Empresário Individual' };
const cliente = r.cliente.replace(/^A CONSTITUIR - /, '');
const quando = r.enviada_em ? DateTime.fromISO(r.enviada_em).setZone('America/Sao_Paulo').toFormat('dd/MM HH:mm') : '';
const teste = /^TESTE/.test(r.resposta_id) ? '[TESTE] ' : '';
let t;
if (r.situacao === 'CONTRATO GERADO') {
  const av = r.detalhe.replace(/^Avisos: /, '');
  t = `${teste}🏢 *Abertura de empresa — contrato pronto para conferência*
*Cliente:* ${cliente}${quando ? ' (formulário enviado em ' + quando + ')' : ''}
*Natureza:* ${nomes[conv.tipo] || conv.tipo}

📄 Contrato: ${r.link_contrato}
📁 Pasta: ${r.link_pasta}`;
  if (av && av !== 'nenhum') t += '

⚠️ *Conferir:*
• ' + av.split(' | ').join('
• ');
  t += '

Confira o contrato antes de seguir com o registro.';
} else if (r.situacao === 'CORRIGIR DADOS') {
  t = `${teste}⚠️ *Abertura de empresa — dados para corrigir*
*Cliente:* ${cliente}${quando ? ' (formulário enviado em ' + quando + ')' : ''}

O robô *não* gerou o contrato nem criou pasta. Corrigir com o cliente:
• ` + r.detalhe.replace(/^Contrato NÃO gerado\. Corrigir:
- /, '').split('
- ').join('
• ') + '

Depois de corrigido, o cliente pode enviar o formulário de novo.';
} else {
  t = `${teste}ℹ️ *Abertura de empresa*
${r.detalhe}`;
}
return [{ json: { space: $('Config').first().json.chat_destino, text: t } }];
